enum AuthService {
 static func call<T:Decodable>(_ config:AuthConfiguration,path:String,body:[String:String],method:String="POST",token:String?=nil) async throws -> T {guard let base=URL(string:config.url),base.scheme=="https",base.host?.hasSuffix(".supabase.co")==true else{throw APIError(message:"Sign-in is not configured.",status:503)};var r=URLRequest(url:base.appendingPathComponent("auth/v1/"+path.components(separatedBy:"?")[0]));if path.contains("?"){r.url=URL(string:r.url!.absoluteString+"?"+path.components(separatedBy:"?")[1])};r.httpMethod=method;r.timeoutInterval=15;r.httpBody=try JSONSerialization.data(withJSONObject:body);r.setValue("application/json",forHTTPHeaderField:"Content-Type");r.setValue(config.key,forHTTPHeaderField:"apikey");if let token{r.setValue("Bearer "+token,forHTTPHeaderField:"Authorization")};let(data,response)=try await URLSession.shared.data(for:r);guard let http=response as? HTTPURLResponse,(200..<300).contains(http.statusCode) else{throw APIError(message:"Sign-in could not be completed. Check the code or try again shortly.",status:(response as? HTTPURLResponse)?.statusCode ?? 0)};return try JSONDecoder().decode(T.self,from:data)}
